head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > dataList]<br/>GridView 컴포넌트에 바인딩할 DataCollection 의 ID 를 설정합니다.",
    "validation" : [
        "GridView 에 바인딩할 DataCollection 의 ID 를 'data:{DataCollection ID}' 형식으로 설정합니다.",
        "바인딩된 DataCollection 의 데이터가 GridView 에 표시됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 미적용 → onpageload 에서 기본값(data:dlt_bind) 선택
    con_dataList.setValue("data:dlt_bind");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
// dataList 는 렌더 시 결정되는 필수 Property(@dynamic N) 이므로,
// GridView 생성 시 con_dataList 셀렉트박스에서 선택한 값(data:{DataCollection ID}) 으로 바인딩한다.
//  - con_dataList 변경은 자동 재생성하지 않고 "Target 재생성" 버튼 클릭 시 본 함수가 재실행되며 반영됨
//  - 바인딩된 DataCollection 의 데이터가 그리드에 표시됨을 DOM 셀 값으로 검증
//  - 바인딩 형식(data:{ID}) 은 options.dataList 로 확인
scwin.comp_init = async function () {
    // 기존 target/dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_bind2 !== 'undefined') {
        $p.data.remove("dlt_bind2");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con 값 조회 : 바인딩할 DataCollection (data:{DataCollection ID} 형식)
    let vDataList = con_dataList.getValue(); // 예) "data:dlt_bind" / "data:dlt_bind2"

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] target1 은 con_dataList 에서 선택한 DataCollection 을 dataList (' + vDataList + ') 형식으로 바인딩한 GridView 로 생성됩니다.\n[절차] con_dataList 값 변경 후 (Target 재생성) 클릭 시 선택한 DataCollection 이 바인딩됩니다.\n[확인] (데이터 표시 확인) 바인딩된 DataCollection 의 데이터가 그리드에 표시되는지 확인합니다.\n[형식] (바인딩 형식 확인) dataList 가 data:{DataCollection ID} 형식(' + vDataList + ')으로 설정되었는지 확인합니다."', '', 'label1');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // GridView 와 바인딩할 DataCollection(DataList) 동적 생성
    //  - 컬럼 구조(name/dept)는 동일, 데이터 값만 상이한 2개의 DataCollection 을 생성
    //  - con_dataList 아이템(data:dlt_bind / data:dlt_bind2)에 각각 대응
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let strDlt2 = '';
    strDlt2 += '<w2:dataList ' + strNameSpace + ' id="dlt_bind2" baseNode="list" repeatNode="map">';
    strDlt2 += '<w2:columnInfo>';
    strDlt2 += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt2 += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt2 += '</w2:columnInfo>';
    strDlt2 += '<w2:data use="true"></w2:data>';
    strDlt2 += '</w2:dataList>';
    $p.data.create(strDlt2);

    dlt_bind.setJSON([
        { "name": "John", "dept": "Sales" },
        { "name": "Jane", "dept": "Dev" },
        { "name": "Jack", "dept": "QA" }
    ], false);

    dlt_bind2.setJSON([
        { "name": "Amy", "dept": "Seoul" },
        { "name": "Bob", "dept": "Busan" },
        { "name": "Cara", "dept": "Daegu" }
    ], false);

    // Property 설정은 createCList 공통 함수 사용 (dataList 바인딩 — con 선택값 data:{DataCollection ID} 형식)
    let properties = {
        dataList: vDataList
    };
    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:420px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="선택한 DataCollection 바인딩 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="부서"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
}



// 데이터 표시 확인 — 바인딩된 DataCollection(dlt_bind) 의 데이터가 그리드 셀에 표시되는지 DOM 에서 확인.
scwin.btn_showData_onclick = function () {
    let rows = [];
    for (let r = 0; r < 3; r++) {
        let c0 = document.querySelector("td[id*='target1_cell_" + r + "_0']");
        let c1 = document.querySelector("td[id*='target1_cell_" + r + "_1']");
        rows.push("row" + r + " : " + (c0 ? c0.innerText.trim() : "") + " / " + (c1 ? c1.innerText.trim() : ""));
    }
    wf_body_bottom.getObj("scwin").setReturnValue("[바인딩 데이터 표시] " + rows.join(", "));
}



// 바인딩 형식 확인 — dataList 가 'data:{DataCollection ID}' 형식으로 설정되었는지(con 선택값 반영) 확인.
scwin.btn_bindFormat_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("바인딩된 DataCollection ID : " + target1.options.dataList);
}
